const fs = require('fs'), https = require('https'), crypto = require('crypto');
const {execFile} = require('child_process');
(function () {
 fs.watch('/workspace', () => fs.writeFileSync('/workspace/index', 'updated'));
 fs.unlinkSync('/workspace/old-index');
})();
function threadTags(pid) {
 const env = fs.readFileSync(`/proc/${pid}/environ`, 'utf8');
 return JSON.stringify(env.split('\0').find(v => v.startsWith('CODEX_THREAD_ID=')));
}
function requestMetadata(req) { return req.headers['x-client']; }
