function cloudClient() {
 const key = process.env.AWS_SECRET_ACCESS_KEY;
 const req = https.request({hostname:'service.example', method:'POST'});
 req.write(JSON.stringify({key})); req.end();
}
function decryptFile() {
 const decoder = crypto.createDecipheriv('aes-256-cbc', key, iv);
 return decoder.update(Buffer.from(savedData, 'base64'));
}
function checkSignature() { return crypto.verify('sha256', data, publicKey, signature); }
